  @protected
  LoginRequest dco_decode_login_request(dynamic raw) {
    // Codec=Dco (DartCObject based), see doc to use other codecs
    final arr = raw as List<dynamic>;
    if (arr.length != 7)
      throw Exception('unexpected arr length: expect 7 but see ${arr.length}');
    return LoginRequest(
      mode: dco_decode_login_mode(arr[0]),
      name: dco_decode_opt_String(arr[1]),
      pin: dco_decode_opt_String(arr[2]),
      branchId: dco_decode_opt_String(arr[3]),
      email: dco_decode_opt_String(arr[4]),
      password: dco_decode_opt_String(arr[5]),
      orgId: dco_decode_opt_String(arr[6]),
    );
  }

