      case 4:
        var var_status = sse_decode_u_16(deserializer);
        var var_code = sse_decode_String(deserializer);
        var var_detail = sse_decode_String(deserializer);
        return MadarError_Server(
          status: var_status,
          code: var_code,
          detail: var_detail,
        );
      case 5:
        var var_detail = sse_decode_String(deserializer);
        return MadarError_Transient(detail: var_detail);
      case 6:
        var var_detail = sse_decode_String(deserializer);
        return MadarError_Internal(detail: var_detail);
      default:
