  @protected
  void sse_encode_realtime_message(
    RealtimeMessage self,
    SseSerializer serializer,
  ) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case RealtimeMessage_Event(eventType: final eventType, data: final data):
        sse_encode_i_32(0, serializer);
        sse_encode_String(eventType, serializer);
        sse_encode_String(data, serializer);
      case RealtimeMessage_ConnectionChanged(connected: final connected):
        sse_encode_i_32(1, serializer);
        sse_encode_bool(connected, serializer);
    }
  }

