@sealed
class MadarBridgeImpl extends RustOpaque implements MadarBridge {
  // Not to be used by end users
  MadarBridgeImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  MadarBridgeImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustBridge.instance.api.rust_arc_increment_strong_count_MadarBridge,
    rustArcDecrementStrongCount:
        RustBridge.instance.api.rust_arc_decrement_strong_count_MadarBridge,
    rustArcDecrementStrongCountPtr:
        RustBridge.instance.api.rust_arc_decrement_strong_count_MadarBridgePtr,
  );

  /// Bind this device with a dashboard activation code (no manager login).
  Future<BranchView> activateDevice({required String code}) => RustBridge
      .instance
      .api
      .crateApiBridgeMadarBridgeActivateDevice(that: this, code: code);

  /// Add a ROUND of the current cart to an existing open ticket. Same offline-first
  /// path as `fire_ticket`; gated behind the original fire if it hasn't synced.
  Future<TicketFiredView> addTicketRound({
    String? tableId,
    required String ticketId,
  }) => RustBridge.instance.api.crateApiBridgeMadarBridgeAddTicketRound(
    that: this,
    tableId: tableId,
    ticketId: ticketId,
  );

  /// The screen to show. Re-read at deliberate transitions only.
  AppRoute appRoute() =>
      RustBridge.instance.api.crateApiBridgeMadarBridgeAppRoute(that: this);

  /// Put a discount on the cart; refused unless allowed or approved.
  Future<void> applyDiscount({
    String? tableId,
    required String kind,
    String? presetId,
    PlatformInt64? amountMinor,
    PlatformInt64? percentBps,
    ApprovalView? approval,
  }) => RustBridge.instance.api.crateApiBridgeMadarBridgeApplyDiscount(
    that: this,
    tableId: tableId,
    kind: kind,
    presetId: presetId,
    amountMinor: amountMinor,
    percentBps: percentBps,
    approval: approval,
  );

  /// A manager approves the act with their own PIN on this device.
  Future<ApprovalView> approveAct({
    required String approverPin,
    required String capKey,
    PlatformInt64? amountMinor,
    PlatformInt64? ageMinutes,
    bool? own,
  }) => RustBridge.instance.api.crateApiBridgeMadarBridgeApproveAct(
    that: this,
    approverPin: approverPin,
    capKey: capKey,
    amountMinor: amountMinor,
    ageMinutes: ageMinutes,
    own: own,
  );

  /// A manager approves this bill's discount with their PIN on this device.
  Future<ApprovalView> approveBillDiscount({
    required String approverPin,
    required String ticketId,
    String? discountId,
    String? discountType,
    double? discountValue,
  }) => RustBridge.instance.api.crateApiBridgeMadarBridgeApproveBillDiscount(
    that: this,
    approverPin: approverPin,
    ticketId: ticketId,
    discountId: discountId,
    discountType: discountType,
    discountValue: discountValue,
  );

  /// Someone holding the grant unlocks one action with their PIN.
  Future<ApprovalView> approveCashSpot({required String approverPin}) =>
      RustBridge.instance.api.crateApiBridgeMadarBridgeApproveCashSpot(
        that: this,
        approverPin: approverPin,
      );

  /// A manager approves a discount on the cart with their PIN.
  Future<ApprovalView> approveDiscount({
    required String approverPin,
    String? tableId,
    required String kind,
    String? presetId,
    PlatformInt64? amountMinor,
    PlatformInt64? percentBps,
  }) => RustBridge.instance.api.crateApiBridgeMadarBridgeApproveDiscount(
    that: this,
    approverPin: approverPin,
    tableId: tableId,
    kind: kind,
    presetId: presetId,
    amountMinor: amountMinor,
    percentBps: percentBps,
  );

  /// A manager approves a queue act on a held order with their PIN.
  Future<ApprovalView> approveDraftAct({
    required String approverPin,
    required String act,
    required String id,
  }) => RustBridge.instance.api.crateApiBridgeMadarBridgeApproveDraftAct(
    that: this,
    approverPin: approverPin,
    act: act,
    id: id,
  );

  /// A manager approves an act on one sale with their PIN.
  Future<ApprovalView> approveOrderAct({
    required String approverPin,
    required String capKey,
    required String orderId,
    PlatformInt64? amountMinor,
  }) => RustBridge.instance.api.crateApiBridgeMadarBridgeApproveOrderAct(
    that: this,
    approverPin: approverPin,
    capKey: capKey,
    orderId: orderId,
    amountMinor: amountMinor,
  );

  /// A manager unlocks this act with their PIN.
  Future<ApprovalView> approveStaffDrink({required String approverPin}) =>
      RustBridge.instance.api.crateApiBridgeMadarBridgeApproveStaffDrink(
        that: this,
        approverPin: approverPin,
      );

  /// A manager approves this waste with their PIN.
  Future<ApprovalView> approveWaste({
    required String approverPin,
    required WasteInput input,
  }) => RustBridge.instance.api.crateApiBridgeMadarBridgeApproveWaste(
    that: this,
    approverPin: approverPin,
    input: input,
  );

  /// Assign / move / unassign a parked draft's table. Errors loudly when the
  /// table is taken (interactive path — the teller picks another).
  Future<void> assignDraftTable({required String id, String? tableId}) =>
      RustBridge.instance.api.crateApiBridgeMadarBridgeAssignDraftTable(
        that: this,
        id: id,
        tableId: tableId,
      );

  /// Attach a customer to a sale already rung (a settled bill by its ticket
  /// id, a finalized online order, a sale in the history), or take them off
  /// with `None`. Offline: queued behind the sale. True while still queued.
  bool attachCustomer({required String orderId, String? customerId}) =>
      RustBridge.instance.api.crateApiBridgeMadarBridgeAttachCustomer(
        that: this,
        orderId: orderId,
        customerId: customerId,
      );

  /// One manager PIN for the whole batch. The signed-in person does not
  /// change. An empty `ids` means everything in the list.
  Future<BatchAuthorizeView> authorizeManagerActions({
    required String approverPin,
    required List<String> ids,
  }) =>
      RustBridge.instance.api.crateApiBridgeMadarBridgeAuthorizeManagerActions(
        that: this,
        approverPin: approverPin,
        ids: ids,
      );

  Future<List<PaymentMethodView>> availablePaymentMethods() => RustBridge
      .instance
      .api
      .crateApiBridgeMadarBridgeAvailablePaymentMethods(that: this);

  /// API base URL the core will talk to (from `.env`).
  String baseUrl() =>
      RustBridge.instance.api.crateApiBridgeMadarBridgeBaseUrl(that: this);

  /// What the bill's discount really takes off, so the manager prompt shows
  /// the figure they are approving rather than a rule.
  BillDiscountView billDiscount({
    required String ticketId,
    String? discountId,
    String? discountType,
    double? discountValue,
  }) => RustBridge.instance.api.crateApiBridgeMadarBridgeBillDiscount(
    that: this,
    ticketId: ticketId,
    discountId: discountId,
    discountType: discountType,
